function muLawEncode(sample) {
  const BIAS = 0x84, CLIP = 32635;
  const sign = sample < 0 ? 0x80 : 0;
  let s = Math.min(Math.round(Math.abs(sample) * 32768), CLIP) + BIAS;
  let exponent = 7;
  for (let mask = 0x4000; (s & mask) === 0 && exponent > 0; exponent--, mask >>= 1) {}
  const mantissa = (s >> (exponent + 3)) & 0x0f;
  return (~(sign | (exponent << 4) | mantissa)) & 0xff;
}

class TalkEncoder extends AudioWorkletProcessor {
  constructor() {
    super();
    this.ratio = sampleRate / 8000;
    this.acc = 0;
    this.buf = [];
  }
  process(inputs) {
    const ch = inputs[0][0];
    if (ch) {
      for (let i = 0; i < ch.length; i++) {
        this.acc += 1;
        if (this.acc >= this.ratio) {
          this.acc -= this.ratio;
          this.buf.push(muLawEncode(ch[i]));
        }
      }
      if (this.buf.length >= 160) { // ~20ms @ 8kHz
        this.port.postMessage(new Uint8Array(this.buf));
        this.buf = [];
      }
    }
    return true;
  }
}
registerProcessor('talk-encoder', TalkEncoder);
